"""Show exact nine-slice panel dimensions and interactive content separately."""
from pathlib import Path
import base64, json, re
folder = Path(__file__).resolve().parent
root = folder.parents[3]
manifest = json.loads((folder / 'panel-kit-manifest.json').read_text())
sheet = 'data:image/png;base64,' + base64.b64encode((folder / 'frames-sheet-v1.png').read_bytes()).decode()
page = '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FreeGuild / empty panel kit</title>
<style>body{margin:0;background:#091426;color:#eaf6ff;font:16px/1.5 system-ui}main{max-width:1500px;margin:auto;padding:24px}h1,h2,a{color:#74dfff}.tools{display:flex;gap:24px;align-items:center;flex-wrap:wrap;margin:16px 0}.tools button,select{font:inherit;padding:8px;background:#102d4e;color:#eaf6ff;border:1px solid #4c86a5}.viewport{aspect-ratio:16/9;position:relative;overflow:hidden;border:1px solid #305475}.stage{width:1920px;height:1080px;position:absolute;transform-origin:0 0;background:linear-gradient(145deg,#56644c,#647c87 45%,#c5bfa9)}.surface{position:absolute;box-sizing:border-box}.plate{position:absolute;inset:12px;background:rgba(11,26,58,var(--plate,.85));pointer-events:none}.frame{position:absolute;inset:0;pointer-events:none;opacity:var(--art,1)}.content{position:absolute;box-sizing:border-box;z-index:1}.content h2{font-size:34px;margin:0 0 24px}.content p{font-size:24px;margin:10px 0}.content .ink{background:#071329;color:#eaf6ff;padding:4px 8px}.action{background:none;border:0;color:#eaf6ff;font:26px system-ui;cursor:pointer;padding:0}.action .content{display:flex;align-items:center;justify-content:center}.action:hover,.action:focus-visible{outline:3px solid #74dfff;outline-offset:-10px}.meter{height:18px;background:#071329;border:1px solid #b8e8ff;margin:10px 0}.meter i{display:block;height:100%;background:#ee6e7d;width:84%}.status-content{display:grid;grid-template-rows:26px 14px 26px 14px;gap:2px}.status-content>span{font-size:24px;line-height:26px}.status-content .meter{height:auto;margin:0}.meter.guard i{background:#71dcf0;width:70%}.stage.gray{filter:grayscale(1)}.guide .content{outline:2px dashed #ffc77d}.guide .surface:after{content:attr(data-size);position:absolute;right:16px;top:6px;font:16px Consolas;background:#071329;color:#ffe4a9;pointer-events:none}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{padding:10px;border-bottom:1px solid #305475;text-align:left}input{accent-color:#74dfff}pre{white-space:pre-wrap;background:#10223b;padding:16px}</style>
<main><h1>Empty panel kit / exact content hosts</h1><p>Generated frame art, measured source cuts, precise reusable layouts. The labels, meters and buttons here are live browser elements. Matching empty Unity prefabs have separate content RectTransforms.</p>
<div class="tools"><button id="boardToggle">Open guild board</button><label><input id="guides" type="checkbox" checked> Dimensions and content bounds</label><label><input id="gray" type="checkbox"> Grayscale</label><label>Frame opacity <input id="art" type="range" min="0" max="1" step=".01" value="1"></label><label>Backing opacity <input id="plate" type="range" min=".7" max="1" step=".01" value=".85"></label></div>
<div class="viewport"><div class="stage guide" id="stage"></div></div><p id="state">Reference canvas: 1920 x 1080. Panel corners: 32 canvas units, fixed during resizing.</p>
<h2>Authored reference dimensions</h2>TABLE
<p>Buttons use an 80-unit control height; hit areas and navigation are independent of art alpha. Frames and scripted accents do not intercept input. Production content stays in the clear host, and text retains its own contrast backing.</p><p><a href="FreeGuild-HUD-Library.html">Supplied icon library</a> | <a href="FreeGuild-HUD-Lab.html">Full layered HUD fixture</a></p>
<details><summary>Source cuts, borders and layout manifest</summary><pre>MANIFEST</pre></details></main>
<script>const spec=SPEC,image=new Image(),stage=document.getElementById('stage');image.src=SHEET;const slices=Object.fromEntries(spec.sprites.map(x=>[x.id,x])),surfaces=Object.fromEntries(spec.surfaces.map(x=>[x.id,x]));let boardVisible=false;
function draw(canvas,slice,w,h){const ctx=canvas.getContext('2d'),[x,y,sw,sh]=slice.top_left_rect_px,b=128,d=32;canvas.width=w;canvas.height=h;const sx=[x,x+b,x+sw-b],sy=[y,y+b,y+sh-b],ssw=[b,sw-2*b,b],ssh=[b,sh-2*b,b],dx=[0,d,w-d],dy=[0,d,h-d],dw=[d,w-2*d,d],dh=[d,h-2*d,d];for(let row=0;row<3;row++)for(let col=0;col<3;col++)if(row!==1||col!==1)ctx.drawImage(image,sx[col],sy[row],ssw[col],ssh[row],dx[col],dy[row],dw[col],dh[row]);}
function panel(id,x,y,parent=stage,button=false){const s=surfaces[id],node=document.createElement(button?'button':'div');node.className='surface'+(button?' action':'');node.style.cssText=`left:${x}px;top:${y}px;width:${s.size[0]}px;height:${s.size[1]}px`;node.dataset.size=s.size.join(' x ');node.innerHTML='<div class="plate"></div><canvas class="frame"></canvas><div class="content"></div>';const content=node.querySelector('.content');content.style.cssText=`inset:${s.padding[1]}px ${s.padding[0]}px`;parent.append(node);draw(node.querySelector('canvas'),slices[s.frame],...s.size);return {node,content};}
function build(){stage.innerHTML='';if(boardVisible){const b=panel('GuildBoard',400,160);b.content.innerHTML='<h2>Guild board <span class="ink">/ Wallet 30</span></h2>';[['Recover the guild marker','Restore the gate route'],['Recover the guild parcel','Activate the preparation stall']].forEach(([title,goal],i)=>{const c=panel('ContractCard',40+i*496,80,b.content);c.content.innerHTML='<h2>'+title+'</h2><p class="ink">'+goal+'</p><p>Content belongs here.</p>';const a=panel('ActionButton',48,344,c.content,true);a.content.textContent='Accept';a.node.onclick=()=>{a.content.textContent='Selected';document.getElementById('state').textContent=title+' / browser intent only; game logic owns acceptance.'};});}else{const hp=panel('StatusPanel',40,40);hp.content.classList.add('status-content');hp.content.innerHTML='<span class="ink">HP 84 / 100</span><div class="meter"><i></i></div><span class="ink">GUARD 42 / 60</span><div class="meter guard"><i></i></div>';const f=panel('FirePanel',40,928);f.content.innerHTML='<p class="ink">FIRE READY / Q</p>';const o=panel('ObjectivePanel',1480,40);o.content.innerHTML='<p class="ink">Return the guild marker</p>';const b=panel('ActionButton',1480,936,stage,true);b.content.textContent='Guild board';b.node.onclick=()=>{boardVisible=true;build()};}}
image.onload=build;document.getElementById('boardToggle').onclick=()=>{boardVisible=!boardVisible;build()};document.getElementById('art').oninput=e=>stage.style.setProperty('--art',e.target.value);document.getElementById('plate').oninput=e=>stage.style.setProperty('--plate',e.target.value);document.getElementById('guides').onchange=e=>stage.classList.toggle('guide',e.target.checked);document.getElementById('gray').onchange=e=>stage.classList.toggle('gray',e.target.checked);new ResizeObserver(()=>stage.style.transform='scale('+stage.parentElement.clientWidth/1920+')').observe(stage.parentElement);
if(new URLSearchParams(location.search).get('demo')==='board')boardVisible=true;
</script></html>'''
import html
values = {'TABLE': '<table><tr><th>Surface</th><th>Outer size</th><th>Content host</th><th>Padding X / Y</th></tr>' + ''.join('<tr><td>'+s['id']+'</td><td>'+str(s['size'])+'</td><td>'+str(s['content_size'])+'</td><td>'+str(s['padding'])+'</td></tr>' for s in manifest['surfaces']) + '</table>',
    'MANIFEST': html.escape(json.dumps(manifest, indent=2)), 'SPEC': json.dumps(manifest), 'SHEET': json.dumps(sheet)}
page = re.sub(r'\b(TABLE|MANIFEST|SPEC|SHEET)\b', lambda match: values[match.group(0)], page)
target = root / 'Documentation/FreeGuild-Panel-Kit.html'
target.write_text(page, encoding='utf-8')
print(target)
